{"operationName":"withWorkRecommendations","variables":{"blacklist":"sailthru","limit":24,"locale":"en","experience":"explore","method":"guruBackoff","from":0},"query":"query withWorkRecommendations($blacklist: String, $limit: Int, $locale: String!, $experience: guru_Experience, $method: guru_WorkRecommendationMethod, $canId: String, $from: Int) {
  cannedWorkRecommendations: unfilteredRecommendedWorks(limit: $limit, blacklist: $blacklist, experience: $experience, method: $method, canId: $canId, from: $from) {
    recommendations {
      work(locale: $locale) {
        id
        workId
        artistId
        matureContent
        ...WorkFieldsForFavoritableItemCarousel
        ...WorkCard
        ...WorkFieldsForFavorites
        ...FeedGrid
        __typename
      }
      __typename
    }
    canId
    canSize
    nextFrom
    hasMore
    from
    limit
    __typename
  }
}

fragment WorkFieldsForFavoritableItemCarousel on Work {
  workId
  __typename
}

fragment WorkCard on Work {
  title
  artistName
  imageUrl
  workId
  availableProductCount
  __typename
}

fragment WorkFieldsForFavorites on Work {
  workId
  __typename
}

fragment FeedGrid on Work {
  id
  matureContent
  ...FeedGridItem
  __typename
}

fragment FeedGridItem on Work {
  id
  artistId
  title
  url
  artist {
    name
    portfolioUrl(locale: $locale)
    avatar
    __typename
  }
  image {
    url
    width
    height
    __typename
  }
  isFavorited
  ...WorkDetails
  __typename
}

fragment WorkDetails on Work {
  id
  title
  isFavorited
  availableProductCount
  modalImage {
    url
    width
    height
    __typename
  }
  ...WorkAttribution
  __typename
}

fragment WorkAttribution on Work {
  title
  url
  artist {
    name
    shopUrl(locale: $locale)
    portfolioUrl(locale: $locale)
    profileUrl(locale: $locale)
    avatar
    __typename
  }
  __typename
}
"}

