{"operationName":"topicProductRecommendationCollection","variables":{"limit":24,"topicLimit":3,"locale":"en","guruLocale":"en","country":"VN","currency":"USD"},"query":"query topicProductRecommendationCollection($limit: Int = 24, $locale: String!, $guruLocale: guru_Locale!, $country: String!, $currency: String!, $topicLimit: Int = 1) {
  topicProductRecommendationListCollection(limit: $limit, locale: $guruLocale, topicLimit: $topicLimit) {
    ...TopicProductFields
    inventoryItems(country: $country, currency: $currency, locale: $locale, unit: IN, previewTypeIds: ["product_close"]) {
      ...InventoryItemFieldsForWhitelist
      ...InventoryItemFieldsForFavoritableItemCarousel
      ...InventoryItemCard
      ...InventoryItemFieldsForFavorites
      __typename
    }
    __typename
  }
}

fragment TopicProductFields on TopicProductRecommendationList {
  topic
  iaCode
  iaDescription(locale: $locale)
  __typename
}

fragment InventoryItemFieldsForWhitelist on ihs_InventoryItemsItem {
  work(locale: $locale) {
    matureContent
    __typename
  }
  price {
    amount
    currency
    __typename
  }
  __typename
}

fragment InventoryItemFieldsForFavoritableItemCarousel on ihs_InventoryItemsItem {
  id
  __typename
}

fragment InventoryItemCard on ihs_InventoryItemsItem {
  productTypeId
  blankItemId
  workId
  description
  previewSet {
    previews {
      previewTypeId
      url
      __typename
    }
    __typename
  }
  price {
    amount
    currency
    discount {
      amount
      percent
      __typename
    }
    __typename
  }
  volumeDiscount {
    thresholds {
      quantity
      percentOff
      __typename
    }
    __typename
  }
  productPageUrl
  work(locale: $locale) {
    artistName
    artistId
    title
    __typename
  }
  __typename
}

fragment InventoryItemFieldsForFavorites on ihs_InventoryItemsItem {
  id
  __typename
}
"}

